      "path": "package.json",
      "content": "{\n  \"name\": \"dsh-need-finder\",\n  \"version\": \"0.3.2\",\n  \"description\": \"Requirement-driven dsh plugin discovery and environment recipes ('点菜, not 逛超市' / 插件界的 dotfiles): plugin_guide matches natural-language needs to a curated directory with a scored match breakdown and category/tag filters plus per-category diversity; recipe installs whole environments from bundled community bundles with ordered plans\",\n  \"type\": \"module\",\n  \"main\": \"lib/index.js\",\n  \"exports\": {\n    \".\": \"./lib/index.js\",\n    \"./match\": \"./lib/match.js\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"lib\",\n    \"cordis.patch.yml\",\n    \"README.md\",\n    \"README.zh.md\",\n    \"ROADMAP.md\"\n  ],\n  \"scripts\": {\n    \"test\": \"node test/match.test.mjs && node test/recipe.test.mjs\"\n  },\n  \"keywords\": [\n    \"deepseek-harness\",\n    \"dsh\",\n    \"dsh-plugin\",\n    \"cordis\",\n    \"plugin\",\n    \"plugin-finder\",\n    \"semantic-search\",\n    \"guide\",\n    \"need-finder\"\n  ],\n  \"license\": \"MIT\",\n  \"publishConfig\": {\n    \"access\": \"public\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    }\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.1\",\n    \"@deepseek-ai/dsh-system-prompt\": \"^0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-tools\": \"^0.1.0-rc.6\",\n    \"@deepseek-ai/schemastery\": \"^3.18.1\"\n  },\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/863683348/dsh-need-finder.git\"\n  },\n  \"homepage\": \"https://github.com/863683348/dsh-need-finder#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/863683348/dsh-need-finder/issues\"\n  }\n}\n"
