      "content": "{\n  \"version\": 1,\n  \"recipes\": [\n    {\n      \"id\": \"notify-suite\",\n      \"name\": \"通知全家桶\",\n      \"nameEn\": \"Notification Suite\",\n      \"description\": \"任务完成通知 + 声音提醒 + 语音回拨，覆盖桌面到手机。\",\n      \"descriptionEn\": \"Turn-completion notifications, sound alerts and voice callbacks — desktop to phone.\",\n      \"tags\": [\"notify\", \"通知\", \"提醒\", \"声音\", \"notification\"],\n      \"order\": 1,\n      \"plugins\": [\n        { \"name\": \"pitetow/dsh-notify-on-complete\", \"order\": 1, \"required\": true },\n        { \"name\": \"huguangyu666/dsh-plugin-notify\", \"order\": 2, \"required\": true },\n        { \"name\": \"CAOGGL/dsh-ding\", \"order\": 3, \"required\": false }\n      ],\n      \"notes\": \"基础通知先装，增强层（语音/回拨）后装；CAOGGL/dsh-ding 可选（Windows 声音提醒）。\"\n    },\n    {\n      \"id\": \"security-audit\",\n      \"name\": \"安全审计套装\",\n      \"nameEn\": \"Security Audit Kit\",\n      \"description\": \"装前静态审计 + 运行中安全守卫 + 遥测脱敏，三层防护。\",\n      \"descriptionEn\": \"Pre-install static audit, runtime security guard, and telemetry redaction in three layers.\",\n      \"tags\": [\"security\", \"audit\", \"安全\", \"审计\", \"扫描\", \"vetting\"],\n      \"order\": 2,\n      \"plugins\": [\n        { \"name\": \"BotonJ/dsh-plugin-sentinel\", \"order\": 1, \"required\": true },\n        { \"name\": \"truelove-dreamer/dsh-plugin-vetting\", \"order\": 2, \"required\": true },\n        { \"name\": \"030611/dsh-telemetry-redactor\", \"order\": 3, \"required\": false }\n      ],\n      \"notes\": \"sentinel 负责安装前审计；vetting 提供 plugin_scan 运行前检查；redactor 可选（脱敏遥测导出）。\"\n    },\n    {\n      \"id\": \"remote-mobile\",\n      \"name\": \"移动远程套装\",\n      \"nameEn\": \"Remote & Mobile Kit\",\n      \"description\": \"手机/局域网远程访问 DSH Web UI，加用量面板。\",\n      \"descriptionEn\": \"Remote access to the DSH Web UI from phone or LAN, plus usage dashboards.\",\n      \"tags\": [\"remote\", \"mobile\", \"手机\", \"远程\", \"局域网\", \"lan\"],\n      \"order\": 3,\n      \"plugins\": [\n        { \"name\": \"Leon0555/dsh-lan-access\", \"order\": 1, \"required\": true },\n        { \"name\": \"mexiaosqwq/dsh-web-mobile\", \"order\": 2, \"required\": false },\n        { \"name\": \"02Muller25/dsh-api-balance\", \"order\": 3, \"required\": false }\n      ],\n      \"notes\": \"先打通局域网访问，再加移动端适配 UI；余额面板可选。\"\n    },\n    {\n      \"id\": \"dev-tools\",\n      \"name\": \"开发效率套装\",\n      \"nameEn\": \"Dev Efficiency Kit\",\n      \"description\": \"页面元素标注、内建能力检查、推理过程可视化。\",\n      \"descriptionEn\": \"Browser element annotation, builtin capability checks, and reasoning visualizers.\",\n      \"tags\": [\"dev\", \"开发\", \"效率\", \"annotate\", \"检查\"],\n      \"order\": 4,\n      \"plugins\": [\n        { \"name\": \"BrambleXu/dsh-annotate\", \"order\": 1, \"required\": true },\n        { \"name\": \"Starfie1d1272/dsh-builtin-toggles\", \"order\": 2, \"required\": true },\n        { \"name\": \"qjcnmd/dsh-reasoning-slider\", \"order\": 3, \"required\": false }\n      ],\n      \"notes\": \"annotate 用于 Vibe Coding 时向 agent 反馈页面元素；builtin-toggles 检查内建能力；reasoning-slider 可选。\"\n    },\n    {\n      \"id\": \"memory-set\",\n      \"name\": \"记忆与上下文套装\",\n      \"nameEn\": \"Memory & Context Kit\",\n      \"description\": \"专注板 + 原生记忆 + 生物记忆，让 agent 跨会话不忘事。\",\n      \"descriptionEn\": \"Focus board plus native and bio-inspired memory so the agent remembers across sessions.\",\n      \"tags\": [\"memory\", \"context\", \"记忆\", \"上下文\", \"专注\", \"笔记\"],\n      \"order\": 5,\n      \"plugins\": [\n        { \"name\": \"highland0971/dsh-native-memory\", \"order\": 1, \"required\": false },\n        { \"name\": \"KLRSL/dsh-biomemory\", \"order\": 2, \"required\": false },\n        { \"name\": \"863683348/dsh-plugin-focus\", \"npm\": \"dsh-plugin-focus\", \"order\": 3, \"required\": true }\n      ],\n      \"notes\": \"原生记忆/生物记忆为可选记忆后端；dsh-plugin-focus 是必装的专注板（已发 npm，可直接 dsh plugin add dsh-plugin-focus）。\"\n    },\n    {\n      \"id\": \"im-bridge\",\n      \"name\": \"IM 桥接（单选）\",\n      \"nameEn\": \"IM Bridge (pick one)\",\n      \"description\": \"微信 / 企业微信 / 钉钉桥接，三选一（互斥示例）。\",\n      \"descriptionEn\": \"WeChat / WeCom / DingTalk bridges — pick exactly one (exclusive example).\",\n      \"tags\": [\"im\", \"wechat\", \"weixin\", \"wecom\", \"dingtalk\", \"微信\", \"钉钉\", \"桥接\", \"聊天\"],\n      \"order\": 6,\n      \"exclusive\": true,\n      \"plugins\": [\n        { \"name\": \"wendayuan/dsh-weixin\", \"order\": 1, \"required\": false },\n        { \"name\": \"michaelcode-wang/dsh-wecom\", \"order\": 1, \"required\": false },\n        { \"name\": \"117BS/dsh-perlica-ding\", \"order\": 1, \"required\": false }\n      ],\n      \"notes\": \"exclusive: 三个渠道互斥，按需只装一个；本 recipe 只负责给选择。\"\n    },\n    {\n      \"id\": \"vision-lab\",\n      \"name\": \"视觉实验室\",\n      \"nameEn\": \"Vision Lab\",\n      \"description\": \"视觉理解 + 图像生成 + 简易视觉工具链。\",\n      \"descriptionEn\": \"Vision understanding, image generation, and an easy vision toolchain.\",\n      \"tags\": [\"vision\", \"image\", \"视觉\", \"图像\", \"截图\", \"生成图片\"],\n      \"order\": 7,\n      \"plugins\": [\n        { \"name\": \"54xkeee/dsh-vision\", \"order\": 1, \"required\": true },\n        { \"name\": \"s3yf1337/dsh-easyvision\", \"order\": 2, \"required\": false },\n        { \"name\": \"dickpy/dsh-imagegen\", \"order\": 3, \"required\": false }\n      ],\n      \"notes\": \"vision 提供图像理解；easyvision 简化接入；imagegen 生成图片（可选）。\"\n    },\n    {\n      \"id\": \"research-stack\",\n      \"name\": \"浏览器研究环境\",\n      \"nameEn\": \"Browser Research Stack\",\n      \"description\": \"浏览器自动化 + 免费搜索 + Tavily 搜索工具。\",\n      \"descriptionEn\": \"Browser automation, free search, and Tavily-powered web tools.\",\n      \"tags\": [\"browser\", \"search\", \"web\", \"浏览器\", \"搜索\", \"抓取\", \"研究\"],\n      \"order\": 8,\n      \"plugins\": [\n        { \"name\": \"wqty123/dsh-browser\", \"order\": 1, \"required\": true },\n        { \"name\": \"DDDMUC/dsh-free-search\", \"order\": 2, \"required\": false },\n        { \"name\": \"1624318455/dsh-plugin-tavily\", \"order\": 3, \"required\": false }\n      ],\n      \"notes\": \"browser 提供网页浏览/抓取；free-search 与 tavily 是搜索后端（任选其一）。\"\n    }\n  ]\n}\n"
